#!/usr/bin/env python3
"""Write (or ``--check``) the synthetic ``off-by-one-consumed`` document of slice S10o-1 and its dumps.

VER04r 8.2 and 16.10 [D36] add the fault ``off-by-one-consumed``: the **second** component ``n`` of a
tuple result (or of the tuple inside an ``Ok``) becomes ``n + 1`` when ``n`` is even and ``n - 1``
when it is odd.  Section 8.2 fixes its JSON, so this directory is the oracle's committed proof that
the registry reproduces it; the generator's slice S10o-2 must reproduce every file below byte for byte.

It is a directory of its own, **not** ``tuple-forms-v1``: the generator's ``tuple_parity.rs`` reproduces
the dumps of that directory byte for byte, so a new fault row there would turn the generator red until
its mirror landed.

Four files are written beside this script (plus ``README.md`` and ``.gitattributes``, which are not
generated):

``off_by_one_consumed_v1.warrant``
    the document (this script's text): a bare tuple with a ``Nat`` second component, bare tuples with
    ``U8`` and ``I8`` second components, ``Result<(U64,Nat),E>`` and ``Result<(I64,Nat),E>`` (the shapes
    of the wasm-leb128 decoders), a ``Result`` with a fixed-width second component, and a 3-tuple whose
    other components must pass through;
``off_by_one_consumed_v1.profile``
    the ``corpus.profile`` the dump uses (one ``fault <op> off-by-one-consumed`` line per op);
``off_by_one_consumed_v1.oracle-faults.json``
    the fault dump (``parity_dumps.faults_view``, open gate): every fault row (the JSON of section 8.2)
    and the controls under the explicit closed gate and the open gate;
``off_by_one_consumed_v1.oracle-refusals.json``
    every signature the fault refuses, with the oracle's code and message.

    python3 make_off_by_one_consumed.py            # (re)write the files
    python3 make_off_by_one_consumed.py --check    # fail if any committed file differs
"""

from __future__ import annotations

import pathlib
import sys

from coding_adventures_warrant_oracle.corpus_v2 import canonical
from coding_adventures_warrant_oracle.errors import OracleError
from coding_adventures_warrant_oracle.faults import fault_row
from coding_adventures_warrant_oracle.lower import lower_document
from coding_adventures_warrant_oracle.parity_dumps import dump_faults
from coding_adventures_warrant_oracle.parser import parse_source

HERE = pathlib.Path(__file__).resolve().parent
NAME = "off_by_one_consumed_v1"

#: ``EXTRA_CLAIMS`` adds a second, restricted claim to an op: ``dec_u64`` also claims its ``Err`` region
#: (``n == 7``, where the model answers ``Err(E.Bad)``), a claim whose stand-in expects only ``Err`` and is
#: therefore proven blind for this fault (VER04r 8.2), the parity contract for a control with a required
#: claim and a blind one.
#:
#: ``(op name, parameters, result type, model body)``: each is also a pure model ``m_<op>`` so a
#: reference claim ``c_<op>`` (``op(args) == m_op(args)``) can see the fault.  ``Nat`` parameters are
#: guarded (``n < 8``) in the op and the claim (a model parameter has no refinement) so the suites stay small.
OPS = [
    ("bare_nat", "a: Bool, n: Nat | n < 8", "(Bool,Nat)", "(a, n)"),
    ("bare_u8", "a: Bool, n: U8", "(Bool,U8)", "(a, n)"),
    ("bare_i8", "a: Bool, n: I8", "(Bool,I8)", "(a, n)"),
    ("dec_u64", "v: U64, n: Nat | n < 8", "Result<(U64,Nat),E>", "if n > 6 then Err(E.Bad) else Ok((v, n))"),
    ("dec_i64", "v: I64, n: Nat | n < 8", "Result<(I64,Nat),E>", "if n > 6 then Err(E.Bad) else Ok((v, n))"),
    ("dec_u8", "a: Bool, n: U8", "Result<(Bool,U8),E>", "if n > 200u8 then Err(E.Bad) else Ok((a, n))"),
    ("tri", "a: U8, n: Nat | n < 8, c: Bool", "(U8,Nat,Bool)", "(a, n, c)"),
]

EXTRA_CLAIMS = {
    "dec_u64": [("err", "v: U64, n: Nat | n == 7", "dec_u64(v, n) == Err(E.Bad)")],
}

PROFILE = (
    "budget 16777216\nchunk_size 1024\nslim_stride auto\n"
    + "".join(f"fault {name} off-by-one-consumed\n" for name, *_ in OPS)
)


def document() -> str:
    out = [
        "warrant off_by_one_consumed v1",
        "  -- Synthetic document of slice S10o-1 (VER04r 8.2, D36): every shape the fault `off-by-one-consumed`",
        "  -- applies to.  GENERATED by make_off_by_one_consumed.py; do not edit by hand.",
        "  error E = Bad | Worse",
        "",
    ]
    for name, params, ret, body in OPS:
        out.append(f"  model m_{name}({params.replace(' | n < 8', '')}) -> {ret} = {body}")
    out.append("")
    for name, params, ret, _ in OPS:
        out.append(f"  op {name}({params}) -> {ret}")
    out += ["  assume platform:", "    none", "  assume environment:", "    none"]
    names = []
    for name, params, _ret, _body in OPS:
        names.append((name, _param_names(params)))
    for name, prms in names:
        out.append(f"  labels {name}:")
        out += [f"    {p} secret" for p in prms]
    for name, prms in names:
        for p in prms:
            out += [f"  input {name}.{p}:", "    hostile", "    ensures no_panic, terminates"]
    for name, _ in names:
        out += [f"  bound {name}:", "    steps <= 64", "    heap <= 0", "    depth <= 8"]
    out.append("")
    for name, params, _ret, _body in OPS:
        args = ", ".join(_param_names(params))
        out += [f"  claim c_{name}:", f"    forall {params}. {name}({args}) == m_{name}({args})"]
        for suffix, eparams, expr in EXTRA_CLAIMS.get(name, []):
            out += [f"  claim c_{name}_{suffix}:", f"    forall {eparams}. {expr}"]
    out.append("")
    return "\n".join(out) + "\n"


def _param_names(params: str) -> list[str]:
    """The parameter names of ``a: Bool, n: Nat | n < 8, c: Bool`` (a ``|`` guard follows its binder)."""
    names = []
    for part in params.split(", "):
        head = part.split(":")[0].strip()
        if ":" in part and head.isidentifier():
            names.append(head)
    return names


#: Signatures the fault refuses: ``(name, document body, op)``.  Every one is a ``generation`` error
#: whose message starts ``fault:`` (the generator's code ``fault``, nothing skipped).
REFUSALS = [
    ("a-scalar-result", "  op f(a: U8) -> U8\n", "f"),
    ("a-bytes-result", "  op f(a: U8) -> Bytes\n", "f"),
    ("a-non-numeric-second-component", "  op f(a: U8) -> (U8,Bool)\n", "f"),
    ("a-bytes-second-component", "  op f(a: U8) -> (U8,Bytes<2>)\n", "f"),
    ("a-result-of-a-scalar", "  op f(a: U8) -> Result<U8,E>\n", "f"),
    ("a-result-with-a-non-numeric-second-component", "  op f(a: U8) -> Result<(Nat,Bool),E>\n", "f"),
    ("an-option-result", "  op f(a: U8) -> Option<(U8,Nat)>\n", "f"),
    ("a-result-of-bytes", "  op f(a: U8) -> Result<Bytes,E>\n", "f"),
    # both defects at once: the oracle reports the second component first, as drop-consumed does
    ("a-non-numeric-second-component-before-the-ok-payload-clash", "  op f(ok_payload: U8) -> (U8,Bool)\n", "f"),
    ("a-parameter-named-ok-payload-in-the-ok-form", "  op f(ok_payload: U8) -> Result<(U8,Nat),E>\n", "f"),
]


def refusals() -> dict:
    """Every refused signature with the oracle's code and message (never echoing input)."""
    rows = []
    for name, body, op in REFUSALS:
        source = "warrant refusals v1\n  error E = A | B\n" + body
        spec = lower_document(parse_source(source.encode()))
        try:
            fault_row(spec.ops[op], "off-by-one-consumed", spec.errors)
        except OracleError as exc:
            rows.append(
                {"name": name, "oracle_code": exc.code, "message": exc.message, "source": source}
            )
        else:
            raise AssertionError(f"{name} was not refused")
    return {"schema": "warrant-faults-refusals-v1", "fault": "off-by-one-consumed", "refusals": rows}


def build() -> dict[pathlib.Path, bytes]:
    doc = document().encode("utf-8")
    profile = PROFILE.encode("utf-8")
    return {
        HERE / f"{NAME}.warrant": doc,
        HERE / f"{NAME}.profile": profile,
        HERE / f"{NAME}.oracle-faults.json": dump_faults(doc, profile, f"{NAME}.warrant", "fixed"),
        HERE / f"{NAME}.oracle-refusals.json": canonical(refusals()),
    }


def run(argv: list[str]) -> int:
    files = build()
    if "--check" in argv:
        bad = [p.name for p, data in files.items() if not p.exists() or p.read_bytes() != data]
        for name in bad:
            print(f"DIFFERS: {name}", file=sys.stderr)
        if not bad:
            print(f"ok: {len(files)} files")
        return 1 if bad else 0
    for path, data in files.items():
        path.write_bytes(data)
        print(f"wrote {path.name} ({len(data)} bytes)")
    return 0


if __name__ == "__main__":
    raise SystemExit(run(sys.argv[1:]))
